#include <stdio.h>
#include <stdlib.h>

int main(void) {
    char riga[128];
    double temp = 0.0;
    char extra = '\0';
    int conteggio = 0;
    int giorni_gelo = 0;
    double somma = 0.0;
    double minima = 0.0;
    double massima = 0.0;

    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        if (sscanf(riga, "%lf %c", &temp, &extra) != 1) {
            fprintf(stderr, "Errore: temperatura non valida.\n");
            return EXIT_FAILURE;
        }
        if (conteggio == 0) {
            minima = temp;
            massima = temp;
        } else {
            if (temp < minima) {
                minima = temp;
            }
            if (temp > massima) {
                massima = temp;
            }
        }
        if (temp <= 0.0) {
            ++giorni_gelo;
        }
        somma += temp;
        ++conteggio;
    }

    if (conteggio == 0) {
        printf("Nessuna temperatura inserita.\n");
        return EXIT_SUCCESS;
    }

    double media = somma / conteggio;
    printf("Letture valide: %d\n", conteggio);
    printf("Minima: %.2f C\n", minima);
    printf("Massima: %.2f C\n", massima);
    printf("Media: %.2f C\n", media);
    printf("Giorni con gelo (<= 0 C): %d\n", giorni_gelo);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    char riga[128];
    long long numero = 0;
    char extra = '\0';

    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%lld %c", &numero, &extra) != 1 ||
        numero < 0 || numero > 1'000'000'000LL) {
        fprintf(stderr, "Errore: inserisci un intero tra 0 e 1000000000.\n");
        return EXIT_FAILURE;
    }

    long long residuo = numero;
    int conteggio_cifre = 0;
    int somma_cifre = 0;
    int cifra_massima = 0;
    long long inverso = 0;

    do {
        int cifra = (int)(residuo % 10);
        ++conteggio_cifre;
        somma_cifre += cifra;
        if (cifra > cifra_massima) {
            cifra_massima = cifra;
        }
        inverso = inverso * 10 + cifra;
        residuo /= 10;
    } while (residuo > 0);

    printf("Numero: %lld\n", numero);
    printf("Cifre: %d\n", conteggio_cifre);
    printf("Somma cifre: %d\n", somma_cifre);
    printf("Cifra massima: %d\n", cifra_massima);
    printf("Numero invertito: %lld\n", inverso);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    char riga[128];
    double capitale_iniziale = 0.0;
    double versamento_mensile = 0.0;
    double tasso_annuo = 0.0;
    int mesi = 0;
    char extra = '\0';

    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%lf %lf %lf %d %c",
               &capitale_iniziale, &versamento_mensile, &tasso_annuo, &mesi, &extra) != 4 ||
        capitale_iniziale < 0.0 || versamento_mensile < 0.0 ||
        tasso_annuo < 0.0 || tasso_annuo > 50.0 || mesi < 1 || mesi > 60) {
        fprintf(stderr, "Errore: parametri del piano non validi.\n");
        return EXIT_FAILURE;
    }

    double tasso_mensile = (tasso_annuo / 100.0) / 12.0;
    double saldo = capitale_iniziale;
    double totale_versato = capitale_iniziale;
    double interessi_totali = 0.0;

    for (int mese = 1; mese <= mesi; ++mese) {
        double interessi = saldo * tasso_mensile;
        interessi_totali += interessi;
        saldo += interessi + versamento_mensile;
        totale_versato += versamento_mensile;
        printf("Mese %2d: interessi = %.2f, saldo = %.2f\n", mese, interessi, saldo);
    }

    printf("Totale versato: %.2f\n", totale_versato);
    printf("Interessi maturati: %.2f\n", interessi_totali);
    printf("Saldo finale: %.2f\n", saldo);
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    constexpr double CAPACITA_MAX = 50.0;
    char riga[128];
    int caricati = 0;
    int scartati = 0;
    int righe_vuote = 0;
    double carico_attuale = 0.0;
    int motivo_arresto = 0;

    while (fgets(riga, (int)sizeof(riga), stdin) != nullptr) {
        char primo = '\0';
        if (sscanf(riga, " %c", &primo) == EOF) {
            ++righe_vuote;
            continue;
        }

        double peso = 0.0;
        char extra = '\0';
        if (sscanf(riga, "%lf %c", &peso, &extra) != 1) {
            fprintf(stderr, "Errore: peso non valido.\n");
            return EXIT_FAILURE;
        }
        if (peso == 0.0) {
            motivo_arresto = 1;
            break;
        }
        if (peso < 0.0) {
            ++scartati;
            continue;
        }
        if (carico_attuale + peso > CAPACITA_MAX) {
            motivo_arresto = 2;
            break;
        }
        carico_attuale += peso;
        ++caricati;
    }

    printf("Pacchi caricati: %d\n", caricati);
    printf("Peso totale: %.2f kg\n", carico_attuale);
    printf("Pacchi scartati: %d\n", scartati);
    printf("Righe vuote ignorate: %d\n", righe_vuote);
    switch (motivo_arresto) {
        case 1:
            printf("Arresto: codice sentinella\n");
            break;
        case 2:
            printf("Arresto: furgone pieno\n");
            break;
        default:
            printf("Arresto: fine dell'input\n");
            break;
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    char riga[128];
    int n = 0;
    char extra = '\0';

    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &n, &extra) != 1 ||
        n < 2 || n > 12) {
        fprintf(stderr, "Errore: inserisci un intero compreso tra 2 e 12.\n");
        return EXIT_FAILURE;
    }

    int conteggio_primi = 0;
    int miglior_numero = 1;
    int max_divisori = 0;

    printf("Tabella di divisibilita (1..%d):\n", n);
    // Invariante esterno: stampate le righe 1..riga_val-1 con statistiche aggiornate
    for (int riga_val = 1; riga_val <= n; ++riga_val) {
        int divisori = 0;
        printf("%2d:", riga_val);
        // Invariante interno: divisori conta i divisori di riga_val in 1..col-1
        for (int col = 1; col <= n; ++col) {
            putchar(' ');
            if (riga_val % col == 0) {
                putchar('X');
                ++divisori;
            } else {
                putchar('.');
            }
        }
        if (divisori == 2) {
            printf(" | divisori: %d (primo)\n", divisori);
            ++conteggio_primi;
        } else {
            printf(" | divisori: %d\n", divisori);
        }
        if (divisori > max_divisori) {
            max_divisori = divisori;
            miglior_numero = riga_val;
        }
    }

    printf("Numeri primi trovati: %d\n", conteggio_primi);
    printf("Numero con piu divisori: %d (%d divisori)\n", miglior_numero, max_divisori);
    return EXIT_SUCCESS;
}
